"""Export a fully offline Plotly dashboard from the frozen model and NASA data."""

from pathlib import Path
import json
import sys
import numpy as np
import pandas as pd
from plotly.offline import get_plotlyjs

sys.path.insert(0, str(Path("src")))
from rul.data import read_raw, SYMBOLS, UNITS
from rul.inference import load_bundle, predict_history

history, si, _ = predict_history(read_raw("data/raw/test_FD001.txt"), load_bundle())
engines = {}
channels = ["s2", "s3", "s4", "s7", "s11", "s12", "s20", "s21"]
for engine, g in history.groupby("engine_id"):
    idx = g.index
    engines[str(engine)] = {
        "c": g.cycle.tolist(),
        "p": g.rul_pred.round(5).tolist(),
        "l": g.lower90.round(5).tolist(),
        "u": g.upper90.round(5).tolist(),
        "s": {s: si.loc[idx, s].round(6).tolist() for s in channels},
    }
payload = {
    "engines": engines,
    "metrics": json.loads(Path("reports/metrics.json").read_text()),
    "comparison": pd.read_csv("reports/model_comparison.csv")
    .round(5)
    .to_dict("records"),
    "official": pd.read_csv("reports/test_predictions.csv").round(5).to_dict("records"),
    "channels": {
        s: {"symbol": SYMBOLS[int(s[1:]) - 1], "unit": UNITS[int(s[1:]) - 1]}
        for s in channels
    },
}
html = r"""<!doctype html>
<html lang="es"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1">
<title>AEROLIFE · RUL Turbofan | UDB</title><style>
:root{--navy:#12314b;--blue:#246ba0;--teal:#158c83;--amber:#d88736;--red:#b94e44;--muted:#60778a;--line:#dce5ed}*{box-sizing:border-box}body{margin:0;background:#f4f7fb;color:var(--navy);font:15px/1.5 system-ui,-apple-system,Segoe UI,sans-serif}header{padding:30px 5% 23px;background:var(--navy);color:white}.eyebrow{font-size:11px;letter-spacing:.13em;color:#b8cfdf}h1{font-size:32px;margin:8px 0 5px;font-weight:650;letter-spacing:-.04em}header p{margin:0;color:#cfdeea;font-size:14px}.layout{display:grid;grid-template-columns:260px 1fr;max-width:1600px;margin:auto;padding:24px 4%;gap:25px}aside{background:white;border:1px solid var(--line);border-radius:14px;padding:21px;height:fit-content;position:sticky;top:16px}h2{font-size:18px;letter-spacing:-.02em;margin:0 0 16px}h3{font-size:15px;margin:0 0 8px}label{font-size:12px;font-weight:650;display:block;margin:18px 0 6px}select,input[type=number]{font:inherit;width:100%;padding:9px;border:1px solid #bdccd9;border-radius:7px;background:#fff;color:var(--navy)}input[type=range]{width:100%;accent-color:var(--blue)}.hint{font-size:11px;color:var(--muted)}.divider{height:1px;background:var(--line);margin:22px 0}.tabs{display:flex;gap:5px;border-bottom:1px solid var(--line);margin-bottom:20px;overflow:auto}.tabs button{border:0;border-bottom:3px solid transparent;background:none;white-space:nowrap;padding:12px 14px;font:600 13px system-ui;color:var(--muted);cursor:pointer}.tabs button.active{color:var(--blue);border-bottom-color:var(--blue)}.cards{display:grid;grid-template-columns:repeat(4,1fr);gap:12px;margin:0 0 18px}.card,.panel{background:white;border:1px solid var(--line);border-radius:12px;padding:18px}.card .label{font-size:11px;text-transform:uppercase;letter-spacing:.04em;color:var(--muted)}.card .value{font-size:27px;font-weight:650;letter-spacing:-.035em;margin-top:4px}.card .unit{font-size:11px;color:var(--muted)}.panel{margin-bottom:18px}.note{background:#edf3f8;border-left:3px solid var(--blue);padding:12px 15px;border-radius:4px;font-size:12px;margin-bottom:18px}.chart{height:340px}.table-wrap{overflow:auto;max-height:420px}table{width:100%;border-collapse:collapse;font-size:12px}th{text-align:left;font-weight:650;background:#edf3f8;position:sticky;top:0}td,th{padding:11px 10px;border-bottom:1px solid #e8eef3;white-space:nowrap}.badge{border-radius:20px;padding:3px 9px;display:inline-block;font-size:10px;font-weight:650}.Revisión{color:var(--red);background:#faeeee}.Planificar{color:#915b1b;background:#fff3e4}.Seguimiento{color:#0b6a62;background:#e8f5f2}.toolbar{display:flex;align-items:center;justify-content:space-between;gap:15px;margin-bottom:14px}.toolbar select{width:auto;max-width:220px}.action{border:1px solid #bccddc;border-radius:7px;background:white;color:var(--blue);font:600 12px system-ui;padding:9px 13px;cursor:pointer}.page{display:none}.page.active{display:block}footer{font-size:11px;color:var(--muted);padding:5px 0 25px}p,li{font-size:13px}.inline-kpis{display:grid;grid-template-columns:repeat(3,1fr);gap:14px}.wide{grid-column:1/-1}#status-current{font-size:17px}.mono{font-family:ui-monospace,monospace}a{color:var(--blue)}@media(max-width:900px){.layout{grid-template-columns:1fr}aside{position:static}.cards{grid-template-columns:repeat(2,1fr)}h1{font-size:25px}.inline-kpis{grid-template-columns:1fr}}@media print{aside,.tabs{display:none}.layout{display:block}.page{display:block!important}.chart{break-inside:avoid}}
</style><script>__PLOTLY__</script></head><body>
<header><div class="eyebrow">UNIVERSIDAD DON BOSCO · DAS172 · PROYECTO INTEGRADOR</div><h1>AEROLIFE · Vida remanente del turbofán</h1><p>NASA C-MAPSS FD001 · degradación del compresor de alta presión · resultados del modelo congelado</p></header>
<div class="layout"><aside><h2>Escenario de revisión</h2><div class="hint">Demostración con motores sintéticos. Abrir este archivo no requiere conexión ni instalación.</div>
<label for="engine">Motor de prueba</label><select id="engine"></select>
<label for="cycle">Ciclo observado <span id="cycle-label"></span></label><input id="cycle" type="range" min="1" value="1">
<div class="hint">El historial mostrado termina en este ciclo.</div>
<div class="divider"></div><label for="horizon">Horizonte H [ciclos]</label><input id="horizon" type="number" min="5" max="60" value="30">
<label for="buffer">Reserva B [ciclos]</label><input id="buffer" type="number" min="0" max="25" value="10">
<label for="maximum">Máximo hasta reevaluar M [ciclos]</label><input id="maximum" type="number" min="1" max="40" value="20">
<div class="divider"></div><div class="hint">La regla de planificación cambia con los controles. El modelo y la evaluación NASA permanecen fijos. Para cargar y predecir nuevos CSV use la aplicación Streamlit incluida.</div></aside>
<main><nav class="tabs"><button class="active" data-page="fleet">01 · Flota</button><button data-page="engine-page">02 · Motor y sensores</button><button data-page="validation">03 · Validación</button><button data-page="method">04 · Método</button></nav>
<section class="page active" id="fleet"><div class="cards" id="fleet-cards"></div><div class="note">Prioridad basada en el límite inferior del intervalo. El presupuesto es para <b>volver a evaluar</b>; no autoriza operar hasta ese límite ni modifica un programa aprobado.</div><div class="panel"><div class="toolbar"><h2>Flota al último ciclo observado</h2><select id="status-filter"><option>Todos</option><option>Revisión prioritaria</option><option>Planificar inspección</option><option>Seguimiento</option></select><button id="export" class="action">Exportar CSV</button></div><div id="fleet-chart" class="chart"></div><div class="table-wrap" id="fleet-table"></div></div></section>
<section class="page" id="engine-page"><div class="cards" id="engine-cards"></div><div class="note" id="engine-note"></div><div class="panel"><h2>Historial causal de RUL</h2><div id="rul-chart" class="chart"></div></div><div class="panel"><div class="toolbar"><h2>Telemetría en unidades de ingeniería</h2><select id="sensor"></select></div><div id="sensor-chart" class="chart"></div></div></section>
<section class="page" id="validation"><div class="cards" id="validation-cards"></div><div class="note" id="interval-note"></div><div class="panel"><h2>Comparación de candidatos · CV por motor</h2><div id="cv-chart" class="chart"></div><div class="table-wrap" id="cv-table"></div></div><div class="panel"><h2>Prueba oficial · último ciclo de 100 motores</h2><div id="test-chart" class="chart"></div></div></section>
<section class="page" id="method"><div class="panel"><h2>Protocolo independiente</h2><p><b>80 motores de desarrollo</b>: GroupKFold de 5 folds con 64 de ajuste y 16 de validación. <b>20 motores de calibración</b>: un punto pseudo-censurado por unidad. <b>100 motores de prueba oficial</b>: evaluación posterior a congelar el modelo.</p><p>Mediana, varianza y escalado se ajustan únicamente en el fold de entrenamiento. Las características son edad, sensores y ventanas causales de 5, 15 y 30 ciclos. El ID y la vida total nunca son predictores.</p><p>El objetivo de ajuste es min(RUL,125). La CV y el resultado principal usan la verdad completa. Las flotas son independientes: train:1 y test:1 son motores distintos. Semilla 42; pseudo-censura semilla 43.</p><p>El intervalo nominal 90% usa el error absoluto de orden 19 entre 20 motores de calibración. Requiere intercambio entre unidades y mecanismo de observación equivalente. La cobertura empírica no representa 90% para un motor concreto ni cobertura simultánea de su trayectoria.</p><h3>Regla configurable</h3><p class="mono">L ≤ B: revisión prioritaria<br>B &lt; L ≤ H+B: planificar inspección<br>L &gt; H+B: seguimiento<br>Reevaluar en floor(min(M,max(0,L-B))) ciclos</p><h3>Alcance</h3><p>FD001 es sintético, una condición de operación y un fallo HPC. No hay eventos AOG, costos ni resultados de inspección. No se afirma ahorro real. Los canales s17 y s19 conservan escala nativa por ambigüedad documental.</p><p><a href="https://www.nasa.gov/intelligent-systems-division/discovery-and-systems-health/pcoe/pcoe-data-set-repository/" target="_blank" rel="noopener">NASA Ames PCoE · fuente original</a> · <a href="https://ntrs.nasa.gov/citations/20090029214" target="_blank" rel="noopener">Saxena et al. (2008)</a></p></div></section>
<footer>Modelo seleccionado y métricas calculados por el pipeline entregado. Exportación autónoma; los gráficos usan únicamente datos incrustados en este archivo.</footer></main></div>
<script>
const D=__DATA__, fmt=(x,n=1)=>Number(x).toFixed(n), $=id=>document.getElementById(id), colors={'Revisión prioritaria':'#b94e44','Planificar inspección':'#d88736','Seguimiento':'#158c83'};
const layout={paper_bgcolor:'white',plot_bgcolor:'white',font:{family:'system-ui',color:'#12314b',size:11},margin:{l:60,r:20,t:25,b:60},legend:{orientation:'h',y:1.16},hovermode:'closest'};const options={responsive:true,displaylogo:false,modeBarButtonsToRemove:['lasso2d','select2d']};
function table(headers,rows){return '<table><thead><tr>'+headers.map(x=>'<th>'+x+'</th>').join('')+'</tr></thead><tbody>'+rows.map(r=>'<tr>'+r.map(x=>'<td>'+x+'</td>').join('')+'</tr>').join('')+'</tbody></table>'}
function card(label,value,unit=''){return '<div class="card"><div class="label">'+label+'</div><div class="value">'+value+'</div><div class="unit">'+unit+'</div></div>'}
function params(){return {h:Math.max(5,Math.min(60,+$('horizon').value||30)),b:Math.max(0,Math.min(25,+$('buffer').value||0)),m:Math.max(1,Math.min(40,+$('maximum').value||20))}}
function decision(l){let {h,b,m}=params();return {s:l<=b?'Revisión prioritaria':l<=h+b?'Planificar inspección':'Seguimiento',r:Math.floor(Math.min(m,Math.max(0,l-b)))}}
let visible=[];
function fleet(){let a=Object.entries(D.engines).map(([id,g])=>{let j=g.c.length-1;return {id:+id,c:g.c[j],p:g.p[j],l:g.l[j],u:g.u[j],...decision(g.l[j])}});let sel=$('status-filter').value;visible=a.filter(x=>sel==='Todos'||x.s===sel).sort((a,b)=>a.l-b.l);let count=s=>visible.filter(x=>x.s===s).length;$('fleet-cards').innerHTML=card('Motores en vista',visible.length)+card('Revisión prioritaria',count('Revisión prioritaria'))+card('Planificar inspección',count('Planificar inspección'))+card('Seguimiento',count('Seguimiento'));let traces=Object.keys(colors).map(s=>{let g=visible.filter(x=>x.s===s);return {type:'bar',name:s,x:g.map(x=>String(x.id)),y:g.map(x=>x.p),marker:{color:colors[s]},error_y:{type:'data',symmetric:false,array:g.map(x=>x.u-x.p),arrayminus:g.map(x=>x.p-x.l),thickness:1,color:'#90a8ba'},hovertemplate:'Motor %{x}<br>RUL %{y:.1f} ciclos<extra>'+s+'</extra>'}});Plotly.react('fleet-chart',traces,{...layout,barmode:'group',xaxis:{title:{text:'Motor de prueba'},type:'category',categoryorder:'array',categoryarray:visible.map(x=>String(x.id))},yaxis:{title:{text:'RUL [ciclos]'}}},options);$('fleet-table').innerHTML=table(['Motor','Ciclo','RUL estimada','Intervalo nominal 90%','Estado','Reevaluar ≤'],visible.map(x=>[x.id,x.c,fmt(x.p),fmt(x.l)+' – '+fmt(x.u),'<span class="badge '+x.s.split(' ')[0]+'">'+x.s+'</span>',x.r+' ciclos']))}
function engine(){let id=$('engine').value,g=D.engines[id],j=Math.max(0,+$('cycle').value-1),d=decision(g.l[j]);$('cycle-label').textContent='· '+g.c[j]+' de '+g.c.length;$('engine-cards').innerHTML=card('Motor',id,'ciclo '+g.c[j])+card('RUL estimada',fmt(g.p[j]),'ciclos')+card('Intervalo nominal 90%',fmt(g.l[j],0)+' – '+fmt(g.u[j],0),'ciclos')+card('Reevaluar en ≤',d.r,'ciclos');$('engine-note').innerHTML='<b>'+d.s+'.</b> '+(j<29?'Historial menor a 30 ciclos: fuera del protocolo de calibración.':'La banda es marginal; no constituye una garantía individual.');let c=g.c.slice(0,j+1),p=g.p.slice(0,j+1),lo=g.l.slice(0,j+1),up=g.u.slice(0,j+1);Plotly.react('rul-chart',[{x:c,y:up,line:{width:0},hoverinfo:'skip',showlegend:false},{x:c,y:lo,line:{width:0},fill:'tonexty',fillcolor:'rgba(36,107,160,.16)',name:'Intervalo nominal 90%'},{x:c,y:p,line:{color:'#246ba0',width:2},name:'RUL estimada'}],{...layout,xaxis:{title:{text:'Ciclo observado'}},yaxis:{title:{text:'RUL [ciclos]'}}},options);let s=$('sensor').value,z=g.s[s].slice(0,j+1),smooth=z.map((_,i)=>{let a=z.slice(Math.max(0,i-14),i+1);return a.reduce((a,b)=>a+b,0)/a.length}),ch=D.channels[s];Plotly.react('sensor-chart',[{x:c,y:z,name:'Medición',line:{color:'#a9bfce',width:1}},{x:c,y:smooth,name:'Media causal 15',line:{color:'#158c83',width:2}}],{...layout,xaxis:{title:{text:'Ciclo observado'}},yaxis:{title:{text:ch.symbol+' ['+ch.unit+']'}}},options)}
function validation(){let m=D.metrics.official_test;$('validation-cards').innerHTML=card('RMSE',fmt(m.rmse,2),'ciclos; verdad sin recortar')+card('MAE',fmt(m.mae,2),'ciclos')+card('R²',fmt(m.r2,3),'100 motores oficiales')+card('Cobertura observada',fmt(m.interval_coverage90*100,0)+'%','ancho medio '+fmt(m.mean_interval_width,1)+' ciclos');$('interval-note').innerHTML='<b>La amplitud limita la priorización.</b> La banda cubre los 100 motores, pero tiene radio '+fmt(m.conformal_radius,2)+' ciclos. Con el escenario por defecto todos los motores generan alerta. NASA score = '+fmt(m.nasa_score,2)+'. IC95% bootstrap del RMSE: ['+m.rmse_ci95_engine_bootstrap.map(x=>fmt(x,2)).join(', ')+'] ciclos.';let a=D.comparison;Plotly.react('cv-chart',[{type:'bar',x:a.map(x=>x.cv_rmse).reverse(),y:a.map(x=>x.candidate).reverse(),orientation:'h',marker:{color:'#246ba0'},error_x:{type:'data',array:a.map(x=>x.cv_sd).reverse()}}],{...layout,margin:{l:160,r:20,t:10,b:55},xaxis:{title:{text:'RMSE CV [ciclos]; barras = DE entre folds'}}},options);$('cv-table').innerHTML=table(['Candidato','RMSE CV','DE folds','MAE CV'],a.map(x=>[x.candidate,fmt(x.cv_rmse,2),fmt(x.cv_sd,2),fmt(x.cv_mae,2)]));let p=D.official;Plotly.react('test-chart',[{x:p.map(x=>x.rul_true),y:p.map(x=>x.rul_pred),text:p.map(x=>'Motor '+x.engine_id),type:'scatter',mode:'markers',marker:{color:'#246ba0',size:7},name:'Motores',hovertemplate:'%{text}<br>Real %{x:.1f}<br>Estimada %{y:.1f}<extra></extra>'},{x:[0,150],y:[0,150],mode:'lines',line:{color:'#90a3b1',dash:'dash'},name:'Ideal'}],{...layout,xaxis:{title:{text:'RUL NASA sin recortar [ciclos]'}},yaxis:{title:{text:'RUL estimada [ciclos]'}}},options)}
Object.keys(D.engines).forEach(id=>$('engine').add(new Option('Motor '+id,id)));Object.entries(D.channels).forEach(([s,ch])=>$('sensor').add(new Option(s+' · '+ch.symbol+' ['+ch.unit+']',s)));$('sensor').value='s3';function selectEngine(){let n=D.engines[$('engine').value].c.length;$('cycle').max=n;$('cycle').value=n;engine()}
$('engine').onchange=selectEngine;$('cycle').oninput=engine;$('sensor').onchange=engine;$('status-filter').onchange=fleet;['horizon','buffer','maximum'].forEach(id=>$(id).oninput=()=>{fleet();engine()});document.querySelectorAll('.tabs button').forEach(b=>b.onclick=()=>{document.querySelectorAll('.tabs button,.page').forEach(x=>x.classList.remove('active'));b.classList.add('active');$(b.dataset.page).classList.add('active');window.dispatchEvent(new Event('resize'))});$('export').onclick=()=>{let rows=[['engine_id','cycle','rul_pred','lower90','upper90','status','revisit_cycles'],...visible.map(x=>[x.id,x.c,x.p,x.l,x.u,x.s,x.r])];let blob=new Blob(['\ufeff'+rows.map(x=>x.join(',')).join('\n')],{type:'text/csv;charset=utf-8'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='priorizacion_fd001.csv';a.click();URL.revokeObjectURL(url)};fleet();selectEngine();validation();window.AEROLIFE={data:D,decision,params};
</script></body></html>"""
html = html.replace("__PLOTLY__", get_plotlyjs()).replace(
    "__DATA__",
    json.dumps(payload, ensure_ascii=False, separators=(",", ":")).replace(
        "</", "<\\/"
    ),
)
Path("reports/Dashboard_RUL_Turbofan.html").write_text(html, encoding="utf-8")
print(
    "Dashboard autónomo generado:",
    Path("reports/Dashboard_RUL_Turbofan.html").stat().st_size,
    "bytes",
)
